WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "note" = $1 , "score" = "s"."score" + $2 WHERE ( true AND ( ( true ) ) AND ( "s"."owner_id" = $3 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" , CAST(CASE WHEN "s"."score" >= $4 THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."score" AS "score" , "c2"."j" AS "owner" ) AS "%")) ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."name" AS "name" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true AND ( ( true ) ) AND ( "s"."id" = $5 ) ) ) LIMIT 1 ) AS "t1" ) AS "c2" ON true ) )
